final showHint = useState(false);
final hintFaded = useState(false);

// Linux-only during-drag seek feedback, rendered into the bottom crumb line.
final isLinux = defaultTargetPlatform == TargetPlatform.linux;
final seekTargetMs = useState<int?>(null);
final seekDurationMs = useState<int?>(null);

return HeroFeedbackSurface(
  flashController: heroFlashController,
  onPlayPause: () => player.playPause(),
  onPrevious: () => player.previous(),
  onNext: () => player.next(),
  onSeek: (d) => player.seek(d),
  positionMs: () => player.songInfo?.position ?? 0,
  durationMs: () => player.songInfo?.duration ?? 0,
  onSeekFeedback: isLinux
      ? ({required int targetMs, required int durationMs}) {
          seekTargetMs.value = targetMs;
          seekDurationMs.value = durationMs;
        }
      : null,
  onSeekFeedbackCleared: isLinux
      ? () {
          seekTargetMs.value = null;
          seekDurationMs.value = null;
        }
      : null,
  onVerticalDragUpdate: acceptVertical ? onHeroVerticalDrag : null,
  onVerticalDragEnd: acceptVertical ? onHeroVerticalDragEnd : null,
  child: child,
);

